        raise TypeError('check_tuples: `tup` must be a list of integers; nothing was proved for anything else')
    if not (_t_ints(k, 1)):
        raise TypeError('check_tuples: `k` must be a list of integers; nothing was proved for anything else')
    tup = _t_tuple(tup)
    k = _t_tuple(k)
    _t_result = _t_core(tup, k)
    return _t_result

def _t_core(tup, k):
    i = 0
    r = True
    # invariant: 0 <= i
    # invariant: i <= len(tup)
    # invariant: r == (forall j in [0, i) . exists m in [0, len(k)) . tup[j] == k[m])
    # decreases: len(tup) - i
    while (i < len(tup)):
        j = 0
        found = False
        # invariant: 0 <= j
        # invariant: j <= len(k)
        # invariant: found == (exists m in [0, j) . tup[i] == k[m])
        # decreases: len(k) - j
        while (j < len(k)):
            if (tup[i] == k[j]):
                found = True
            j = (j + 1)
        if found:
            pass
        else:
            r = False
        i = (i + 1)
    return r

def _t_tuple(v):
    return tuple(_t_tuple(x) for x in v) if isinstance(v, (list, tuple)) else v

def _t_ints(v, depth):
    if depth == 0:
        return isinstance(v, int) and not isinstance(v, bool)
    return isinstance(v, (list, tuple)) and all(_t_ints(x, depth - 1) for x in v)

